// Avalia a resposta do GET /api/techniques, filtra o que espera revisao humana
// e monta UMA nota diaria. Idempotencia: arquivo deterministico por lote (data local)
// + dedupe por chave id|status. Nunca emite comando de movimento nem altera status.
const items = $input.all();
const first = items.length ? items[0].json : {};

// Falha da API (no HTTP Request com continueOnFail o item traz a propriedade 'error').
if (first.error || (first.techniques === undefined && first.total === undefined)) {
  const raw = first.error;
  const msg = typeof raw === 'string' ? raw : ((raw && raw.message) || 'sem resposta');
  return [{ json: { ok: false, failure: 'API da Usami indisponivel: ' + msg + '. Nenhuma nota gravada.', batchDate: null } }];
}

const THRESHOLD = 0.8;
const techniques = Array.isArray(first.techniques) ? first.techniques : [];

// Chave deterministica do lote: data no fuso local do servidor (America/Sao_Paulo).
const batchDate = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Sao_Paulo', year: 'numeric', month: '2-digit', day: '2-digit',
}).format(new Date());

// Filtro: status 'proposta' + confidence abaixo do limiar + fontes presentes.
// Dedupe por id|status para nunca repetir a mesma tecnica dentro do lote.
const seen = new Set();
const pending = [];
for (const t of techniques) {
  const id = String(t && t.id || '');
  const status = String(t && t.status || '');
  const key = id + '|' + status;
  if (!id || seen.has(key)) continue;
  seen.add(key);
  const conf = Number(t.confidence);
  const hasSources = Array.isArray(t.sources) && t.sources.length > 0;
  if (status === 'proposta' && Number.isFinite(conf) && conf < THRESHOLD && hasSources) {
    pending.push(t);
  }
}
pending.sort((a, b) => String(a.id).localeCompare(String(b.id)));

const generatedAt = new Date().toISOString();
const lines = [];
lines.push('---');
lines.push('source: usami-automation');
lines.push('kind: technique-review');
lines.push('generated_at: ' + generatedAt);
lines.push('batch_date: ' + batchDate);
lines.push('review_status: proposta');
lines.push('confidence_threshold: ' + THRESHOLD);
lines.push('pending_count: ' + pending.length);
lines.push('total_techniques_seen: ' + techniques.length);
lines.push('---');
lines.push('');
lines.push('# Revisao de tecnicas - ' + batchDate);
lines.push('');
lines.push('Lista assincrona da base de conhecimento: tecnicas em status `proposta`, com confianca abaixo de ' + THRESHOLD + ' e com fontes (sources) registradas, aguardando aprovacao HUMANA.');
lines.push('');
lines.push('> Regra de ouro: nada aqui movimenta o avatar. Este workflow NAO emite comando de movimento e NAO aprova nem altera status de tecnica. A aprovacao (proposta -> validada) e decisao de uma PESSOA feita pela API da Usami (ex.: POST /api/technique com o status desejado); o n8n apenas lista e nunca chama endpoint de escrita.');
lines.push('');
lines.push('## Pendentes de aprovacao humana (' + pending.length + ')');
lines.push('');
if (pending.length === 0) {
  lines.push('(nenhuma tecnica atende ao filtro de revisao neste lote)');
} else {
  for (const t of pending) {
    const motions = Array.isArray(t.motions) ? t.motions.join(', ') : '(nenhuma)';
    const sources = Array.isArray(t.sources) ? t.sources.join(', ') : '(nenhuma)';
    lines.push('- **' + t.name + '** (`' + t.id + '`) - status: ' + t.status + ', confianca: ' + t.confidence);
    lines.push('  - motions: ' + motions);
    lines.push('  - sources: ' + sources);
    lines.push('  - Acao: humano revisa a ficha em `usami/data/techniques/' + t.id + '.json` e aprova ou rejeita pela API.');
  }
}
lines.push('');
lines.push('---');
lines.push('_Gerado por \'Usami - Revisao de Tecnicas (agendado)\'. Lote ' + batchDate + '. Rodar duas vezes no mesmo dia sobrescreve esta mesma nota (arquivo deterministico por data): sem nota duplicada e sem reprocessar tecnica ja listada._');

const filename = 'technique-review-' + batchDate + '.md';
const markdown = lines.join('\n');
return [{ json: { ok: true, batchDate, filename, markdown, pendingCount: pending.length } }];
